package fixture

import "testing"

func TestAnagram(t *testing.T) {
	if !Anagram("listen", "silent") {
		t.Fatal("listen/silent should be anagrams")
	}
	if Anagram("abc", "abd") {
		t.Fatal("abc/abd should not be anagrams")
	}
}
